// Preparar payload para Resend con PDF adjunto
const inputData = $input.first().json;
const binaryData = $input.first().binary;

let pdfBase64 = null;
if (binaryData) {
  const keys = Object.keys(binaryData);
  if (keys.length > 0) {
    const pdfData = binaryData[keys[0]];
    if (pdfData?.data) {
      pdfBase64 = typeof pdfData.data === 'string' 
        ? pdfData.data 
        : Buffer.from(pdfData.data).toString('base64');
    }
  }
}

const attachments = pdfBase64 ? [{
  filename: `CV_${inputData.job_title.replace(/[^a-z0-9]/gi, '_')}.pdf`,
  content: pdfBase64
}] : [];

const payload = {
  from: 'contacto@iaavanza.com',
  to: inputData.candidate_email,
  subject: inputData.subject,
  html: inputData.email_body,
  attachments: attachments
};

return {
  json: {
    ...inputData,
    resend_payload: payload,
    has_pdf: pdfBase64 !== null
  }
};

