const inputData = $input.first().json;

// ====== CONFIGURACIÓN DE SEGURIDAD ======
const MODO_PRUEBA = true; // ⬅️ CAMBIAR A false EN PRODUCCIÓN
const EMAIL_PRUEBA = "mavtuasistentevirtual@gmail.com";

// Validaciones obligatorias
const errores = [];

// 1. Verificar que existen datos básicos
if (!inputData.candidate_name || inputData.candidate_name === "Candidato") {
  errores.push("❌ No se pudo extraer el nombre del candidato");
}

if (!inputData.candidate_email || inputData.candidate_email === "email@ejemplo.com") {
  errores.push("❌ No se pudo extraer el email del candidato");
}

if (!inputData.job_title || inputData.job_title === "Sin título") {
  errores.push("❌ No hay título de la oferta");
}

if (!inputData.score || inputData.score < 50) {
  errores.push("⚠️ Score demasiado bajo para enviar");
}

if (!inputData.cv_html_completo || inputData.cv_html_completo.length < 100) {
  errores.push("❌ CV no generado correctamente");
}

// 2. Si hay errores, detener el flujo
if (errores.length > 0) {
  throw new Error(`VALIDACIÓN FALLIDA:\n${errores.join('\n')}`);
}

// 3. En modo prueba, forzar tu email
if (MODO_PRUEBA) {
  inputData.candidate_email = EMAIL_PRUEBA;
  inputData.subject = `[PRUEBA] ${inputData.subject}`;
  console.log(`🧪 MODO PRUEBA ACTIVO - Email redirigido a ${EMAIL_PRUEBA}`);
}

// 4. Logging de seguridad
console.log('✅ VALIDACIÓN EXITOSA');
console.log(`📧 Enviando email a: ${inputData.candidate_email}`);
console.log(`📊 Score: ${inputData.score}%`);
console.log(`👤 Candidato: ${inputData.candidate_name}`);

return {
  json: inputData,
  binary: $input.first().binary
};

// Limitar a 15 ofertas para scoring inicial
